+        return form;
+    }
+
+    private Grid<Message> createGrid() {
+        // Who wrote and what they wrote come first; how to reach them follows.
+        sentMessages.addColumn(Message::name).setKey("name").setHeader("Name").setAutoWidth(true);
+        sentMessages.addColumn(Message::text).setKey("message").setHeader("Message").setFlexGrow(1);
+        sentMessages.addColumn(Message::email).setKey("email").setHeader("Email").setAutoWidth(true);
+        sentMessages.addColumn(Message::phone).setKey("phone").setHeader("Phone").setAutoWidth(true);
+        sentMessages.setAllRowsVisible(true);
+        sentMessages.setMinHeight("10em");
+        return sentMessages;
+    }
+
+    @Override
+    protected void onAttach(AttachEvent attachEvent) {
+        super.onAttach(attachEvent);
+        refreshMessages();
+    }
+
+    private void refreshMessages() {
+        sentMessages.setItems(MessageStore.current().messages());
+    }
+
+    private void fieldEdited(HasValidation field) {
+        if (clearing) {
+            return;
+        }
+        clearError(field);
+        send.setEnabled(true);
+    }
+
+    private void sendOnEnter() {
+        if (send.isEnabled() && leaveDialog == null) {
+            trySend();
+        }
+    }
+
+    private void trySend() {
+        String nameValue = valueOf(name);
+        String emailValue = valueOf(email);
+        String phoneValue = valueOf(phone);
+        String messageValue = valueOf(message);
+
+        clearErrors();
+        boolean valid = true;
+        if (nameValue.isEmpty()) {
+            showError(name, NAME_REQUIRED);
+            valid = false;
+        }
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            showError(email, EMAIL_INVALID);
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            showError(email, EMAIL_OR_PHONE_REQUIRED);
+            valid = false;
+        }
+        if (messageValue.isEmpty()) {
+            showError(message, MESSAGE_REQUIRED);
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            showError(message, MESSAGE_TOO_LONG);
+            valid = false;
+        }
+        if (!valid) {
+            return;
+        }
+
+        MessageStore.current().add(new Message(nameValue, emailValue, phoneValue, messageValue));
+        refreshMessages();
+        emptyForm();
+        send.setEnabled(false);
+        Notification.show("Message sent").addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+    }
+
+    private void emptyForm() {
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearing = false;
+        }
+        clearErrors();
+    }
+
+    private void clearErrors() {
+        clearError(name);
+        clearError(email);
+        clearError(phone);
+        clearError(message);
+    }
+
+    private static void showError(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private static void clearError(HasValidation field) {
+        field.setInvalid(false);
+        field.setErrorMessage(null);
+    }
+
+    private static String valueOf(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value.trim();
+    }
+
+    private boolean isDirty() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!isDirty()) {
+            return;
+        }
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Leave without sending?");
+        dialog.add(new Paragraph("Your message has not been sent. If you leave now, it is lost."));
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Button discard = new Button("Discard", clicked -> {
+            closeLeaveDialog();
+            action.proceed();
+        });
+        // Cancelling, rather than just forgetting the action, leaves the router
+        // ready to ask again the next time the view is left.
+        Button keepEditing = new Button("Keep editing", clicked -> {
+            closeLeaveDialog();
+            action.cancel();
+        });
+        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        dialog.getFooter().add(discard, keepEditing);
+
+        leaveDialog = dialog;
+        dialog.open();
+    }
+
+    private void closeLeaveDialog() {
+        if (leaveDialog != null) {
+            leaveDialog.close();
+            leaveDialog.removeFromParent();
+            leaveDialog = null;
+        }
+    }
+}
