+import com.microsoft.playwright.options.AriaRole;
+
+/**
+ * The same behaviour as {@link ContactViewTest}, seen through a real browser.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    @BeforeAll
+    static void startBrowser() {
+        setup();
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        cleanup();
+    }
+
+    @BeforeEach
+    void openPage() throws Exception {
+        setupTest();
+    }
+
+    @AfterEach
+    void closePage() {
+        cleanupTest();
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private void assertHeadingIs(String text) {
+        assertThat(page.locator("h1")).hasText(text);
+    }
+
+    @Test
+    void headingAndFormAreShown() {
+        assertHeadingIs("Contact");
+        assertThat(aboutLink()).hasAttribute("router-link", "");
+        send().assertEnabled();
+        name().assertValue("");
+    }
+
+    @Test
+    void emptyForm_showsTheErrorsInPlace() {
+        send().click();
+
+        name().assertErrorMessage(ContactView.NAME_REQUIRED);
+        email().assertErrorMessage(ContactView.EMAIL_OR_PHONE_REQUIRED);
+        message().assertErrorMessage(ContactView.MESSAGE_REQUIRED);
+        send().assertEnabled();
+    }
+
+    @Test
+    void malformedEmail_showsItsOwnError() {
+        name().setValue("Ada");
+        email().setValue("not-an-email");
+        message().setValue("Hello");
+        send().click();
+
+        email().assertErrorMessage(ContactView.EMAIL_INVALID);
+    }
+
+    @Test
+    void sending_notifiesListsAndEmptiesTheForm() {
+        name().setValue("Ada");
+        email().setValue("ada@example.com");
+        message().setValue("Hello there");
+        send().click();
+
+        NotificationElement notification = new NotificationElement(page);
+        notification.assertOpen();
+        assertTrue(notification.getText().contains("Message sent"));
+
+        GridElement grid = GridElement.get(page);
+        assertEquals("Ada", grid.findCell(0, 0).orElseThrow().getCellContentLocator().textContent());
+        assertEquals("Hello there", grid.findCell(0, 1).orElseThrow().getCellContentLocator().textContent());
+
+        name().assertValue("");
+        email().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("Grace");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enter_sendsAndTheListSurvivesLeavingAndComingBack() {
+        name().setValue("Grace");
+        phone().setValue("040 123 4567");
+        message().setValue("Sent with Enter");
+        message().getInputLocator().press("Enter");
+
+        new NotificationElement(page).assertOpen();
+        GridElement grid = GridElement.get(page);
+        assertThat(grid.findCell(0, 1).orElseThrow().getCellContentLocator()).hasText("Sent with Enter");
+
+        aboutLink().click();
+        assertHeadingIs("About");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("Contact")).click();
+        assertHeadingIs("Contact");
+
+        assertThat(GridElement.get(page).findCell(0, 0).orElseThrow().getCellContentLocator()).hasText("Grace");
+    }
+
+    @Test
+    void aboutLink_navigatesWithoutReloading() {
+        page.evaluate("window.notReloaded = true");
+        aboutLink().click();
+
+        assertHeadingIs("About");
+        assertEquals(Boolean.TRUE, page.evaluate("window.notReloaded === true"));
+    }
+
+    @Test
+    void leavingAnEmptyForm_isNotInterrupted() {
+        aboutLink().click();
+
+        assertHeadingIs("About");
+        new DialogElement(page).assertClosed();
+    }
+
+    @Test
+    void leavingAStartedForm_asksFirst() {
+        name().setValue("Ada");
+        aboutLink().click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        dialog.assertClosed();
+        assertHeadingIs("Contact");
+        name().assertValue("Ada");
+
+        aboutLink().click();
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertHeadingIs("About");
+    }
+}
