+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContactView() {
+        navigate(ContactView.class);
+        findFields();
+    }
+
+    private void findFields() {
+        name = find(TextField.class).withLabel("Name").single();
+        email = find(EmailField.class).withLabel("Email").single();
+        phone = find(TextField.class).withLabel("Phone").single();
+        message = find(TextArea.class).withLabel("Message").single();
+        send = find(Button.class).withText("Send").single();
+    }
+
+    private void fillIn(String nameValue, String emailValue, String phoneValue, String messageValue) {
+        test(name).setValue(nameValue);
+        test(email).setValue(emailValue);
+        test(phone).setValue(phoneValue);
+        test(message).setValue(messageValue);
+    }
+
+    private Grid<?> grid() {
+        return find(Grid.class).single();
+    }
+
+    @Test
+    void view_hasHeadingAndAboutLinkAndEmptyEnabledForm() {
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertTrue(find(RouterLink.class).withText("About").exists());
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled());
+        assertFalse(name.isInvalid());
+    }
+
+    @Test
+    void aboutLink_navigatesToAboutView() {
+        test(find(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyForm_reportsNameEmailAndMessage() {
+        test(send).click();
+
+        assertTrue(name.isInvalid());
+        assertEquals(ContactView.NAME_REQUIRED, name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals(ContactView.EMAIL_OR_PHONE_REQUIRED, email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals(ContactView.MESSAGE_REQUIRED, message.getErrorMessage());
+
+        assertFalse(find(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void malformedEmail_isReported() {
+        fillIn("Ada", "not-an-email", "", "Hello");
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals(ContactView.EMAIL_INVALID, email.getErrorMessage());
+        assertFalse(name.isInvalid());
+        assertFalse(message.isInvalid());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void phoneAlone_isEnough() {
+        fillIn("Ada", "", "+358 40 123 4567", "Hello");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void emailAlone_isEnough() {
+        fillIn("Ada", "ada@example.com", "", "Hello");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void longMessage_isReported() {
+        fillIn("Ada", "ada@example.com", "", "x".repeat(501));
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals(ContactView.MESSAGE_TOO_LONG, message.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void messageOfExactlyMaximumLength_isSent() {
+        fillIn("Ada", "ada@example.com", "", "x".repeat(500));
+        test(send).click();
+
+        assertFalse(message.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void failedSend_keepsWhatWasTyped() {
+        fillIn("", "ada@example.com", "", "Hello");
+        test(send).click();
+
+        assertEquals("ada@example.com", email.getValue());
+        assertEquals("Hello", message.getValue());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void successfulSend_notifiesListsAndEmptiesTheForm() {
+        fillIn("Ada", "ada@example.com", "", "Hello there");
+        test(send).click();
+
+        assertTrue(test(find(Notification.class).single()).getText().contains("Message sent"));
+
+        var grid = test(grid());
+        assertEquals(1, grid.size());
+        assertEquals("Ada", grid.getCellText(0, grid.getColumnPosition("name")));
+        assertEquals("Hello there", grid.getCellText(0, grid.getColumnPosition("message")));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(name.isInvalid());
+        assertFalse(send.isEnabled());
+    }
+
+    @Test
+    void sendIsEnabledAgain_afterTheNextEdit() {
+        fillIn("Ada", "ada@example.com", "", "Hello");
+        test(send).click();
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("Grace");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void enter_sendsTheMessage() {
+        fillIn("Ada", "ada@example.com", "", "Hello");
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void messages_areListedNewestFirstAndSurviveLeaving() {
+        fillIn("Ada", "ada@example.com", "", "First");
+        test(send).click();
+        fillIn("Grace", "grace@example.com", "", "Second");
+        test(send).click();
+
+        var grid = test(grid());
+        assertEquals("Grace", grid.getCellText(0, grid.getColumnPosition("name")));
+        assertEquals("Ada", grid.getCellText(1, grid.getColumnPosition("name")));
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        var revisited = test(grid());
+        assertEquals(2, revisited.size());
+        assertEquals("Grace", revisited.getCellText(0, revisited.getColumnPosition("name")));
+    }
+
+    @Test
+    void leavingAnEmptyForm_isNotInterrupted() {
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertFalse(find(Dialog.class).exists());
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void leavingAStartedForm_asksFirstAndKeepEditingStays() {
+        test(name).setValue("Ada");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(find(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test(find(Button.class).withText("Keep editing").single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Ada", name.getValue());
+        assertFalse(find(Dialog.class).exists());
+
+        // Leaving again asks again, rather than slipping through.
+        test(find(RouterLink.class).withText("About").single()).click();
+        assertTrue(find(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+    }
+
+    @Test
+    void leavingAStartedForm_discardGoesOn() {
+        test(message).setValue("Half written");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+        test(find(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingFromAnywhereElse_alsoAsksFirst() {
+        test(phone).setValue("040 123 4567");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue(find(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+    }
+
+    @Test
+    void aboutView_hasItsHeading() {
+        navigate(AboutView.class);
+        assertEquals("About", find(H1.class).single().getText());
+    }
+}
